import csv,collections
SYM="_ H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac".split()
ROM={1:'I',2:'II',3:'III',4:'IV',5:'V',6:'VI',9:'IX',11:'XI',8:'VIII',15:'XV',16:'XVI'}
M=collections.defaultdict(dict)
for r in csv.DictReader(open('/mnt/project/COORDINATES-2_13.csv',encoding='utf-8')):
    if r['grade']=='measured':
        k=(int(r['Z']),int(r['charge'])); l=int(r['l'])
        M[k][l]=float(r['delta'])           # last write wins; duplicates are per-J rows
full={k:v for k,v in M.items() if all(l in v for l in (0,1,2,3))}
print("species with measured delta at l=0,1,2,3 :",len(full))
def name(k):
    Z,c=k; return f"{SYM[Z] if Z<len(SYM) else 'Z'+str(Z)} {ROM.get(c,c)}"
res=[]
for k,d in sorted(full.items()):
    # even map (M odd, e.g. M=7): p = 6-2l ; odd map (M even, e.g. M=8): p = 7-2l
    e={6-2*l:d[l] for l in (0,1,2,3)}; o={7-2*l:d[l] for l in (0,1,2,3)}
    f1=e[0]-2*e[2]+e[4]; f2=2*e[0]-3*e[2]+e[6]
    f4=o[1]-2*o[3]+o[5]; f5=o[3]-2*o[5]+o[7]
    res.append((name(k),f1,f2,f4,f5))
for n,a,b,c,dd in res: print(f"  {n:8s} f1{a:+9.4f} f2{b:+9.4f} f4{c:+9.4f} f5{dd:+9.4f}")
import statistics
for i,lab in ((1,'facet1'),(2,'facet2'),(3,'facet4'),(4,'facet5')):
    vals=[r[i] for r in res]; sat=sum(1 for v in vals if v<0)
    print(f"{lab}: satisfied {sat}/{len(vals)}")
EOF

